result:
**The bug:** `jwt.verify()` internally rejects tokens when `now > exp` (strictly greater), so it *accepts* tokens where `exp === now`. The manual check uses `<` (same logic), so that edge case slips through both gates. Fix: use `<=`.

**Second issue:** the catch block swallows all errors with a generic message, hiding the distinction between an expired token and a malformed one.

Here's the fixed middleware:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    // clockTimestamp forces jwt.verify to use the same time reference as our check below
    const decoded = jwt.verify(token, process.env.JWT_SECRET, {
      clockTimestamp: Math.floor(Date.now() / 1000),
    });

    // Fix: <= rejects tokens expiring at exactly the current second
    if (decoded.exp !== undefined && decoded.exp <= Date.now() / 1000) {
      return res.status(401).json({ error: 'Token expired' });
    }

    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    if (err.name === 'NotBeforeError') {
      return res.status(401).json({ error: 'Token not yet valid' });
    }
    // Unexpected errors shouldn't leak details to the client
    console.error('Auth middleware error:', err);
    res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Summary of changes:**

| Issue | Before | After |
|---|---|---|
| Boundary bug | `decoded.exp < now` accepts `exp === now` | `decoded.exp <= now` correctly rejects it |
| Clock sync | `jwt.verify` and manual check used independent `Date.now()` calls, risking a race | `clockTimestamp` pins both to the same instant |
| Error handling | All errors → generic 401 | `TokenExpiredError`, `JsonWebTokenError`, `NotBeforeError` each get distinct messages; unexpected errors → 500 without leaking internals |
